<?php
namespace LaraSelector\Http; use Illuminate\Http\Request; use Illuminate\Routing\Controller; use LaraSelector\LaraSelectorToken;
final class LaraSelectorController extends Controller {public function capabilities(Request $r){return response()->json(['protocol'=>1,'capabilities'=>['resolve','editor-uri']]);}public function handshake(Request $r){if(!$this->sameOrigin($r))return $this->error('origin_denied',403);$t=bin2hex(random_bytes(24));session(['laraselector_token'=>$t]);return response()->json(['ok'=>true])->header('X-LaraSelector-Token',$t);}public function resolve(Request $r,LaraSelectorToken $tokens){if(!$this->sameOrigin($r)||!hash_equals((string)session('laraselector_token'),(string)$r->header('X-LaraSelector-Token')))return $this->error('access_denied',403);try{$s=$tokens->resolve((string)$r->input('id'));}catch(\InvalidArgumentException $e){return $this->error('invalid_source',422,$e->getMessage());}$p=$s['path'];foreach(config('laraselector.path_mapping',[])as$f=>$t)if(str_starts_with($p,$f))$p=$t.substr($p,strlen($f));$scheme=config('laraselector.editor')==='cursor'?'cursor':'vscode';return response()->json(['source'=>['path'=>$s['relative'],'line'=>$s['line']],'editorUri'=>$scheme.'://file/'.str_replace('%2F','/',rawurlencode($p)).':'.$s['line'].':1']);}private function sameOrigin(Request $r):bool{$o=$r->header('Origin');return$o===null||$o===$r->getSchemeAndHttpHost();}private function error(string$c,int$s,?string$d=null){return response()->json(['error'=>['code'=>$c,'message'=>$d?:$c]],$s);}}
